var $corr = 0

include "cede.main.xc"
include "screen.xc"


function @headingDeviation() : number

	// Normalize the correction to the range [-180, 180]
	if ($corr > 180) 
		$corr -= 360;
	else
		if ($corr < -180) 
			$corr += 360;


	return $corr;



update
	$corr = $heading - $currentheading
	;print(text("correction currently is: {}",@headingDeviation()))

var $screen = screen(10,0);


update	
	var $speed = input_number(4,0);

	;When
	if($speed > -1)
		var $direction = input_number(3,5)
		if($direction < -0.01 )
			if($heading < 1)
				$heading += 360
			if($corr > -5)
				$heading -= 1
		else 
			if($direction > 0.01)
				if($heading > 358)
					$heading -= 360;			
				if($corr < 5)
					$heading += 1







	var $lon = input_number(4,9)
	var $lat = input_number(4,8)
	$screen.blank(color(0,0,0,0));
	$screen.write(0,0,blue,text("heading:{} ", round($heading*10)/10))
	$screen.write(0,10,blue,text("lat:{}", round($lat*100)/100))
	$screen.write(0,20,blue,text("lon:{}", round($lon*100)/100))
